// A 30-day spend series with a believable shape: quiet weekends, one heavy day.
function buildSeries() {
  const shape = [
    18, 24, 31, 27, 9, 4, 22, 35, 41, 29, 12, 6, 33, 48,
    52, 44, 15, 7, 38, 61, 57, 49, 19, 8, 43, 88, 64, 51, 26, 11,
  ];
  const today = new Date(t0);
  today.setHours(0, 0, 0, 0);
  return shape.map((v, i) => {
    const d = new Date(today);
    d.setDate(d.getDate() - (shape.length - 1 - i));
    return {
      date: d.toISOString().slice(0, 10),
      costUSD: v,
      tokensOut: v * 41_000,
      tokensAll: v * 2_600_000,
    };
  });
}

function mountDemo(app) {
  const series = buildSeries();
  const sum = (n, field) => series.slice(-n).reduce((a, r) => a + r[field], 0);

  app.get('/api/sessions', (req, res) => {
    // ?all=1 would normally skip the newest-per-project collapse. Every demo
    // session is already a distinct project, so both views hold the same rows.
    const sessions = SESSIONS.map(s => ({ ...s }));
    res.json({
      sessions,
      totals: {
        costUSD: sessions.reduce((a, s) => a + s.costUSD, 0),
        tokensOut: sessions.reduce((a, s) => a + s.tokensOut, 0),
        tokensIn: sessions.reduce((a, s) => a + s.tokensIn, 0),
        sessionCount: 269,
        shownCount: sessions.length,
        // Every demo session is a distinct project, so the newest-per-project
        // collapse holds nothing back and the toggle has nothing to reveal.
        hiddenCount: 0,
        hiddenStaleCount: 0,
      },
      usage: {
        todayCost: sum(1, 'costUSD'),
        todayTokens: sum(1, 'tokensAll'),
        cost7d: sum(7, 'costUSD'),
        cost30d: sum(30, 'costUSD'),
        tokens30d: sum(30, 'tokensAll'),
        topModel: 'claude-opus-5',
        series,
      },
      serverTime: new Date().toISOString(),
    });
  });

  app.get('/api/sessions/:id/log', (req, res) => {
    res.json(LOGS[req.params.id] || []);
  });

  app.get('/api/sessions/:id/subagents/:agentId', (req, res) => {
    const session = SESSIONS.find(s => s.sessionId === req.params.id);
    const sub = session && session.subagents.find(a => a.agentId === req.params.agentId);
    if (!sub) return res.status(404).json({ error: 'Unknown subagent' });
    const detail = SUBAGENT_DETAIL[sub.agentId] || { result: '', steps: [] };
    res.json({
      agentId: sub.agentId,
      agentType: sub.agentType,
      model: sub.model,
      status: sub.status,
      task: sub.task,
      tokensOut: sub.tokensOut,
      toolCount: sub.toolCount,
      durationMs: new Date(sub.lastEventAt) - new Date(sub.startedAt),
      result: detail.result,
      truncated: false,
      steps: detail.steps,
    });
  });

  app.get('/api/sessions/:id/tasks/:taskId', (req, res) => {
    const session = SESSIONS.find(s => s.sessionId === req.params.id);
    const task = session && session.backgroundTasks.find(t => t.taskId === req.params.taskId);
    if (!task) return res.status(404).json({ error: 'Unknown task' });
    res.json({
      ...task,
      truncated: false,
      output: TASK_OUTPUT[task.taskId] || '',
    });
  });

  app.get('/api/sessions/:id/tools/:toolUseId', (req, res) => {
    const d = TOOL_DETAIL[req.params.toolUseId];
    if (!d) return res.status(404).json({ error: 'Unknown tool call' });
    res.json({
      toolUseId: req.params.toolUseId,
      name: d.name,
      input: d.input,
      done: d.done !== false,
      ok: d.ok,
      summary: d.summary,
      durationMs: d.durationMs,
      persisted: false,
      truncated: false,
      output: d.output,
    });
  });

  // Opening a folder that does not exist would only raise an error dialog.
  app.post('/api/open-folder', (req, res) => res.json({ ok: true, demo: true }));
}

module.exports = { mountDemo };
